sourcesContent:
export type EmotionType = 'happy' | 'sad' | 'anxious' | 'angry' | 'lonely' | 'neutral' 
  | 'hopeful' | 'confused' | 'frustrated' | 'guilty' | 'shameful' | 'proud';

export type RiskLevel = 'low' | 'medium' | 'high' | 'critical';

export type ProblemCategory = 
  | 'academic_stress'     // 学业压力
  | 'interpersonal'       // 人际关系
  | 'family_relationship' // 家庭关系
  | 'romantic_relationship' // 恋爱关系
  | 'career_future'       // 职业未来
  | 'self_identity'       // 自我认同
  | 'emotion_regulation'  // 情绪调节
  | 'body_image'          // 身体意象
  | 'addiction'           // 成瘾问题
  | 'trauma'              // 创伤经历
  | 'other';              // 其他

export interface EmotionAnalysis {
  emotion: EmotionType;
  confidence: number;
  keywords: string[];
  secondaryEmotions: EmotionType[];
}

export interface RiskAssessment {
  level: RiskLevel;
  keywords: string[];
  warningMessage: string;
  hotline: string;
}

export interface ProblemAnalysis {
  category: ProblemCategory;
  confidence: number;
  keywords: string[];
  subcategories: string[];
}

export interface EmotionStyle {
  greeting: string;
  tone: string;
  color: string;
  emoji: string;
}

export interface Message {
  id: string;
  type: 'user' | 'bot';
  content: string;
  knowledgeSources?: KnowledgeItem[];
  similarQuestions?: SimilarQuestion[];
  emotion?: EmotionAnalysis;
  risk?: RiskAssessment;
  problem?: ProblemAnalysis;
  emotionStyle?: EmotionStyle;
  report?: string;
  timestamp?: string;
}

export interface KnowledgeItem {
  question: string;
  answer: string;
}

export interface SimilarQuestion {
  question: string;
  description: string;
  keywords: string;
  answers: Answer[];
  similarity: number;
}

export interface Answer {
  answer_text: string;
  has_label: boolean;
  labels_sequence: string[];
}

export interface InterventionInfo {
  frameworkId: string;
  frameworkName: string;
}

export interface CarePlanSuggestion {
  categoryName: string;
  suggestion: string;
}

export interface AnalysisSources {
  emotion: 'rule' | 'llm' | 'hybrid';
  risk: 'rule' | 'llm' | 'hybrid';
  problem: 'rule' | 'llm' | 'hybrid';
}

export interface QuestionResponse {
  question: string;
  description?: string;
  answer: string;
  knowledgeSources: KnowledgeItem[];
  similarQuestions: SimilarQuestion[];
  summary: string;
  emotion: EmotionAnalysis;
  risk: RiskAssessment;
  problem: ProblemAnalysis;
  emotionStyle: EmotionStyle;
  intervention?: InterventionInfo;
  carePlan?: CarePlanSuggestion;
  analysisSources?: AnalysisSources;
  llmUsed?: boolean;
  report: string;
  responseTimeMs?: number;
}

export interface GroupedHistoryItem {
  time: string;
  user: string;
  bot: string;
  summary: string;
  tags: string[];
  group: string;
}

export interface UserProgress {
  totalTimes: number;
  history: Array<{
    time: string;
    user: string;
    bot: string;
    summary: string;
    stressLevel?: number;
    anxietyLevel?: number;
    moodStability?: number;
    emotion?: string;
    risk?: string;
    problem?: string;
  }>;
}

export interface HistoryDataPoint {
  date: string;
  stressLevel: number;
  anxietyLevel: number;
  moodStability: number;
}

export const EMOTION_NAMES: Record<EmotionType, string> = {
  happy: '开心',
  sad: '低落',
  anxious: '焦虑',
  angry: '愤怒',
  lonely: '孤独',
  neutral: '平稳',
  hopeful: '充满希望',
  confused: '迷茫困惑',
  frustrated: '挫败',
  guilty: '内疚',
  shameful: '羞愧',
  proud: '自豪'
};

export const PROBLEM_CATEGORY_NAMES: Record<ProblemCategory, string> = {
  academic_stress: '学业压力',
  interpersonal: '人际关系',
  family_relationship: '家庭关系',
  romantic_relationship: '恋爱关系',
  career_future: '职业未来',
  self_identity: '自我认同',
  emotion_regulation: '情绪调节',
  body_image: '身体意象',
  addiction: '成瘾问题',
  trauma: '创伤经历',
  other: '其他'
};

export const RISK_LEVEL_NAMES: Record<RiskLevel, string> = {
  low: '低',
  medium: '中',
  high: '高',
  critical: '严重'
};
